-- Demo source for Ask Wabi Insight: Sharjah International Airport flight movements, calendar year 2025.
-- The rows are generated by generate.py (synthetic, modelled on the real route network and carriers);
-- load the three CSV files with bcp after running this script (see README.md).
IF DB_ID('SharjahAirport2025') IS NULL CREATE DATABASE SharjahAirport2025;
GO
USE SharjahAirport2025;
GO
IF OBJECT_ID('dbo.Flights') IS NOT NULL DROP TABLE dbo.Flights;
IF OBJECT_ID('dbo.Airlines') IS NOT NULL DROP TABLE dbo.Airlines;
IF OBJECT_ID('dbo.Airports') IS NOT NULL DROP TABLE dbo.Airports;
CREATE TABLE dbo.Airlines (AirlineCode nvarchar(3) NOT NULL PRIMARY KEY, AirlineName nvarchar(100) NOT NULL, Country nvarchar(60) NOT NULL);
CREATE TABLE dbo.Airports (IataCode nvarchar(3) NOT NULL PRIMARY KEY, AirportName nvarchar(120) NOT NULL, City nvarchar(60) NOT NULL, Country nvarchar(60) NOT NULL, Region nvarchar(60) NOT NULL);
CREATE TABLE dbo.Flights (
  FlightId int NOT NULL PRIMARY KEY,
  FlightNumber nvarchar(8) NOT NULL,
  AirlineCode nvarchar(3) NOT NULL REFERENCES dbo.Airlines(AirlineCode),
  Direction nvarchar(10) NOT NULL,            -- Departure | Arrival (relative to Sharjah)
  OtherAirportCode nvarchar(3) NOT NULL REFERENCES dbo.Airports(IataCode),
  ScheduledTime datetime2(0) NOT NULL,
  ActualTime datetime2(0) NULL,
  DelayMinutes int NULL,                      -- NULL for cancelled flights
  Status nvarchar(10) NOT NULL,               -- On Time | Delayed | Cancelled | Diverted
  AircraftType nvarchar(20) NOT NULL,
  Seats int NOT NULL,
  Passengers int NOT NULL,
  Terminal nvarchar(2) NOT NULL,
  Gate nvarchar(4) NOT NULL,
  FlightDate date NOT NULL,
  DayOfWeek nvarchar(9) NOT NULL,
  DayOfWeekNumber tinyint NOT NULL,           -- 1 = Monday
  MonthNumber tinyint NOT NULL,
  MonthName nvarchar(9) NOT NULL,
  Quarter tinyint NOT NULL,
  HourOfDay tinyint NOT NULL,
  BlockMinutes int NOT NULL
);
CREATE INDEX IX_Flights_Date ON dbo.Flights(FlightDate, Direction);
CREATE INDEX IX_Flights_Airline ON dbo.Flights(AirlineCode);
CREATE INDEX IX_Flights_Airport ON dbo.Flights(OtherAirportCode);
GO
-- Read-only login for the Wabi Insight application registration (change the password).
IF SUSER_ID('shj_reader') IS NULL CREATE LOGIN shj_reader WITH PASSWORD = 'Shj#Reader#2025!', CHECK_POLICY = OFF;
IF DATABASE_PRINCIPAL_ID('shj_reader') IS NULL CREATE USER shj_reader FOR LOGIN shj_reader;
ALTER ROLE db_datareader ADD MEMBER shj_reader;
GO
